import{_ as t,o,c as n,ah as r}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse(`{"title":"L'Éclosion","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/activites/eclosion.md","filePath":"src/guide/activites/eclosion.md"}`),s={name:"guide/activites/eclosion.md"};function i(a,e,l,c,u,p){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="l-eclosion" tabindex="-1">L&#39;Éclosion <a class="header-anchor" href="#l-eclosion" aria-label="Permalink to &quot;L&#39;Éclosion&quot;">​</a></h1><p>L&#39;Éclosion est le programme d&#39;incubation de NextBoxx. Il est ouvert aux anciens apprenants <strong>Canopé</strong>, aux <strong>porteurs externes</strong> et aux <strong>lauréats de concours</strong>. Il fonctionne par <strong>cycles</strong>, avec une date limite de candidature.</p><h2 id="candidater" tabindex="-1">Candidater <a class="header-anchor" href="#candidater" aria-label="Permalink to &quot;Candidater&quot;">​</a></h2><p>Tout compte peut candidater depuis <strong>Activités → Mon projet L&#39;Éclosion</strong>, <strong>une fois par cycle</strong>, tant que les dépôts sont ouverts (la page affiche la date de clôture). S&#39;il n&#39;y a aucun cycle ouvert, la page le dit.</p><p>Renseignez :</p><ul><li>le <strong>nom du projet</strong> et son <strong>secteur</strong> ;</li><li>le <strong>problème</strong> auquel il répond et la <strong>solution</strong> proposée ;</li><li>l&#39;<strong>avancement</strong> : prototype, premiers clients, équipe, chiffres ;</li><li>un <strong>pitch</strong> en PDF, facultatif (5 Mo au plus).</li></ul><p>L&#39;<strong>origine</strong> de la candidature est conservée : la voie « Canopé » n&#39;est proposée qu&#39;à un compte au statut Canopé ; les autres candidatent comme porteurs externes. Les <strong>lauréats de concours</strong> sont saisis pour leur compte par le Chargé d&#39;incubation.</p><p>Le Chargé d&#39;incubation examine votre candidature et vous informe de sa décision. Si votre projet est <strong>retenu</strong>, vous devenez <strong>Porteur de projet</strong> et une participation de NextBoxx peut vous être proposée. Vous suivez la candidature, la décision et la participation validée sur la même page. Si le projet est refusé, vous recevez le motif.</p><h2 id="piloter-les-cycles-charge-d-incubation" tabindex="-1">Piloter les cycles (Chargé d&#39;incubation) <a class="header-anchor" href="#piloter-les-cycles-charge-d-incubation" aria-label="Permalink to &quot;Piloter les cycles (Chargé d&#39;incubation)&quot;">​</a></h2><p>Le Chargé d&#39;incubation gère <strong>Activités → L&#39;Éclosion</strong>.</p><ol><li><strong>Nouveau cycle</strong> : titre, <strong>clôture des dépôts</strong>, <strong>début</strong> et <strong>fin</strong> de l&#39;incubation. Les dépôts ferment au plus tard au début de l&#39;incubation. Le cycle est créé en <strong>brouillon</strong> : personne ne peut encore y candidater.</li><li><strong>Ouvrir aux candidatures</strong> : les comptes peuvent candidater jusqu&#39;à la clôture.</li><li><strong>Saisir un lauréat</strong> : retrouvez le compte par son adresse e-mail, avec le nom et l&#39;année du concours. C&#39;est possible jusqu&#39;à la fin de l&#39;incubation.</li><li><strong>Examiner</strong> chaque candidature, avec ses pièces : <strong>Retenir le projet</strong>, ou <strong>Refuser</strong> avec un motif. Seul le Chargé d&#39;incubation décide.</li></ol><h2 id="la-participation-et-le-comite-d-investissement" tabindex="-1">La participation et le comité d&#39;investissement <a class="header-anchor" href="#la-participation-et-le-comite-d-investissement" aria-label="Permalink to &quot;La participation et le comité d&#39;investissement&quot;">​</a></h2><p>Pour un projet retenu sans participation en cours, le Chargé <strong>propose une participation</strong> : le <strong>type</strong> (prise de capital, ou part du chiffre d&#39;affaires), le <strong>pourcentage</strong> et les <strong>conditions</strong> (durée, clause de sortie, contreparties). <strong>Soumettre au comité</strong> la place « Au comité ».</p><p>Le <strong>comité d&#39;investissement</strong> comprend trois sièges : le <strong>Chargé d&#39;incubation</strong>, le <strong>Coordinateur pédagogique</strong> et la <strong>Direction</strong>. Il décide <strong>à l&#39;unanimité</strong> :</p><ul><li>la proposition vaut le <strong>vote pour</strong> du Chargé ;</li><li>le Coordinateur et la Direction votent ensuite, <strong>chacun depuis un compte différent</strong> (une personne ne siège pas deux fois sur la même participation) ;</li><li>un <strong>vote contre</strong>, avec son motif, <strong>refuse</strong> la participation ; le Chargé reçoit le motif et peut en proposer une nouvelle.</li></ul><p>Les membres votent depuis <strong>Activités → Comité d&#39;investissement</strong>, qui liste les participations <strong>À voter</strong> et les décisions récentes. Une participation n&#39;est <strong>activée qu&#39;une fois validée</strong> par les trois voix. La Direction voit le portefeuille des participations validées.</p>',16)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
